using Mediator;

// Runs right before SaveChangesAsync, like every domain event handler
public sealed class PublishOrderPlaced(IMessageBus bus)
    : INotificationHandler<OrderPlaced>
{
    public async ValueTask Handle(OrderPlaced e, CancellationToken ct)
    {
        // The domain event itself becomes the public message,
        // and it leaves before the order is committed
        await bus.PublishAsync(e, ct);
    }
}

using Mediator;

// The public contract: primitives only, versioned, owned by this service
public sealed record OrderPlacedV1(
    Guid OrderId, Guid CustomerId, decimal Total);

// Same timing, but it only stages a row in the same transaction
public sealed class StageOrderPlaced(ShopDb db)
    : INotificationHandler<OrderPlaced>
{
    public ValueTask Handle(OrderPlaced e, CancellationToken ct)
    {
        var message = new OrderPlacedV1(e.OrderId, e.CustomerId, e.Total);
        db.Outbox.Add(OutboxMessage.From(message)); // commits with the order
        return ValueTask.CompletedTask;
    }
}

