using Microsoft.EntityFrameworkCore;

public sealed class OutboxRelay(IServiceScopeFactory scopes, IMessageBus bus)
    : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stop)
    {
        while (!stop.IsCancellationRequested)
        {
            using var scope = scopes.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<ShopDb>();
            var pending = await db.Outbox.Where(x => x.PublishedAt == null)
                .OrderBy(x => x.Id).Take(50).ToListAsync(stop);
            foreach (var m in pending)
            {
                // A crash between these lines sends it again next time
                await bus.PublishAsync(m.Type, m.Payload, stop);
                m.PublishedAt = DateTime.UtcNow;
                await db.SaveChangesAsync(stop);
            }
            await Task.Delay(TimeSpan.FromSeconds(1), stop);
        }
    }
}
